INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn,ipa,example1,example1_cn,example2,example2_cn) VALUES ('am3_l56','make a living','',NULL,'/meɪk ə ˈlɪvɪŋ/','We could not make a living without the river.','没有这条河我们就无法谋生。','He makes a living as a carpenter.','他靠做木匠维持生计。') ON CONFLICT (lesson_id,us) DO UPDATE SET ipa=EXCLUDED.ipa,example1=EXCLUDED.example1,example1_cn=EXCLUDED.example1_cn,example2=EXCLUDED.example2,example2_cn=EXCLUDED.example2_cn;
INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn,ipa,example1,example1_cn,example2,example2_cn) VALUES ('am3_l56','out of order','',NULL,'/aʊt əv ˈɔːrdər/','The flood put the phone out of order.','洪水使电话出了故障。','The elevator is out of order today.','电梯今天坏了。') ON CONFLICT (lesson_id,us) DO UPDATE SET ipa=EXCLUDED.ipa,example1=EXCLUDED.example1,example1_cn=EXCLUDED.example1_cn,example2=EXCLUDED.example2,example2_cn=EXCLUDED.example2_cn;
INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn,ipa,example1,example1_cn,example2,example2_cn) VALUES ('am3_l56','take turns','',NULL,'/teɪk tɜːrnz/','We took turns watching the river from the attic.','我们轮流从阁楼盯着河。','The children took turns on the swing.','孩子们轮流荡秋千。') ON CONFLICT (lesson_id,us) DO UPDATE SET ipa=EXCLUDED.ipa,example1=EXCLUDED.example1,example1_cn=EXCLUDED.example1_cn,example2=EXCLUDED.example2,example2_cn=EXCLUDED.example2_cn;
INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn,ipa,example1,example1_cn,example2,example2_cn) VALUES ('am3_l56','stand to lose','',NULL,'/stænd tə luːz/','With the cattle safe, we stood to lose little.','牲口安全了,我们几乎不会有损失。','They stood to lose everything in the storm.','他们在风暴中可能失去一切。') ON CONFLICT (lesson_id,us) DO UPDATE SET ipa=EXCLUDED.ipa,example1=EXCLUDED.example1,example1_cn=EXCLUDED.example1_cn,example2=EXCLUDED.example2,example2_cn=EXCLUDED.example2_cn;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l56',5,'am3_l56_gp1','choice','{"stem":"\"If we kept our secrets from the river, misfortune might ___ us.\"(与现在相反虚拟,主句 might + 原形)","options":["overtook","overtake","to overtake","overtakes"],"answer_index":1,"stem_cn":"若我们对河隐瞒秘密,不幸也许会突然降临。","explanation_cn":"与现在相反的虚拟:if we kept…(过去式)时主句用 might + 动词原形。✓ misfortune might overtake us. ✗ overtakes / overtook / to overtake:might 后接动词原形 overtake。"}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l56',5,'am3_l56_gp1','choice','{"stem":"\"Without the river, we ___ not make a living here.\"(没有…就不能:without 引导虚拟,主句用情态词过去式)","options":["will","can","could","may"],"answer_index":2,"stem_cn":"没有这条河,我们无法在此谋生。","explanation_cn":"Without…(=If it were not for…)引导与现在相反的虚拟,主句用情态词的过去式 could + 原形。✓ we could not make a living. ✗ can(不是虚拟)/ will / may:此处用 could。"}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l56',5,'am3_l56_gp1','choice','{"stem":"\"If the river ___ higher, the whole meadow would flood.\"(与现在相反虚拟,if 从句用过去式)","options":["has risen","rose","will rise","rises"],"answer_index":1,"stem_cn":"如果河再涨高些,整片草场都会被淹。","explanation_cn":"与现在相反的虚拟,if 从句用一般过去式。✓ If the river rose higher… ✗ rises(不是虚拟)/ has risen / will rise:虚拟条件从句用过去式 rose。"}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l56',5,'am3_l56_gp2','choice','{"stem":"\"Their house had sound foundations; it would have ___ even if it had been submerged.\"(与过去相反,主句 would have + 过去分词)","options":["stood up","stand","stood","standing"],"answer_index":2,"stem_cn":"他们的房子地基牢固,即便被淹也会屹立不倒。","explanation_cn":"与过去相反的虚拟,主句用 would have + 过去分词。✓ it would have stood. ✗ stand / stood up / standing:would have 后用过去分词 stood。"}'::jsonb,4) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l56',5,'am3_l56_gp2','choice','{"stem":"\"The house would have stood even if it ___ almost submerged.\"(与过去相反,if 从句用过去完成式)","options":["had been","were","has been","was"],"answer_index":0,"stem_cn":"即便房子几乎被淹,它也会挺住。","explanation_cn":"与过去相反的虚拟,if 从句用过去完成式 had + 过去分词。✓ even if it had been almost submerged. ✗ was / were(现在相反才用 were)/ has been:过去相反用 had been。"}'::jsonb,5) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l56',5,'am3_l56_gp2','choice','{"stem":"\"If they had trusted the foundations, they ___ have panicked.\"(与过去相反,主句 would/might + have + 过去分词)","options":["will not","do not","may not","might not"],"answer_index":3,"stem_cn":"若他们信任地基,就不会惊慌。","explanation_cn":"与过去相反的虚拟,主句用 would/might + have + 过去分词。✓ they might not have panicked. ✗ may not(要用过去式 might)/ will not / do not:此处用 might not。"}'::jsonb,6) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l56',5,'am3_l56_gp3','choice','{"stem":"\"They ___ have become frightened by the flood, judging by their haste.\"(对过去的推测“一定…了”,填表肯定推测的词)","options":["would","must","need","can"],"answer_index":1,"stem_cn":"从他们的慌乱看,他们一定是被洪水吓着了。","explanation_cn":"对过去的肯定推测“一定…了”用 must + have + 过去分词。✓ They must have become frightened. ✗ can(疑问/否定才用)/ would / need:表肯定推测用 must。"}'::jsonb,7) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l56',5,'am3_l56_gp3','choice','{"stem":"\"The river ___ have risen very fast that night.\"(对过去的肯定推测,填表推测的词)","options":["must","ought","shall","dare"],"answer_index":0,"stem_cn":"那天夜里河水一定涨得极快。","explanation_cn":"对过去的肯定推测,填 must。✓ The river must have risen very fast. ✗ shall / ought(须加 to)/ dare:表推测“一定”用 must。"}'::jsonb,8) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l56',5,'am3_l56_gp3','choice','{"stem":"\"A predecessor of ours must ___ built this boathouse long ago.\"(must ___ 过去分词:对过去的推测,填这个助动词)","options":["has","having","have","had"],"answer_index":2,"stem_cn":"我们的一位前辈一定在很久前造了这座船坞。","explanation_cn":"must + have + 过去分词构成对过去的推测;此处填中间的助动词 have。✓ must have built. ✗ has / had / having:must 后一律用 have + 过去分词。"}'::jsonb,9) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l56',5,'am3_l56_gp4','choice','{"stem":"\"We welcome spring by the water, ___ the youngest child with flowers.\"(现在分词作伴随状语,主动)","options":["crowning","crowned","to crown","crown"],"answer_index":0,"stem_cn":"我们在水边迎接春天,给最小的孩子戴上花冠。","explanation_cn":"现在分词短语作伴随状语,主动“给…戴花冠”。✓ crowning the youngest child with flowers. ✗ crowned(被动)/ crown / to crown:表主动伴随用 -ing。"}'::jsonb,10) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l56',5,'am3_l56_gp4','choice','{"stem":"\"We end the year by the river, ___ a green wreath into the current.\"(现在分词作伴随状语)","options":["throw","throwing","to throw","thrown"],"answer_index":1,"stem_cn":"我们在河边辞旧岁,把一只绿花环抛入水流。","explanation_cn":"现在分词短语作伴随状语,主动“把…抛入”。✓ throwing a green wreath into the current. ✗ thrown(被动)/ throw / to throw:主动伴随用 -ing。"}'::jsonb,11) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l56',5,'am3_l56_gp4','choice','{"stem":"\"___ thanks for the harvest, we gather by the river each fall.\"(现在分词短语置于句首作状语)","options":["Giving","To giving","Given","Give"],"answer_index":0,"stem_cn":"为丰收致谢,我们每年秋天都聚在河边。","explanation_cn":"现在分词短语置于句首作状语,主动“为…致谢”。✓ Giving thanks for the harvest, we gather… ✗ Given(被动)/ Give / To giving:主动用现在分词 Giving。"}'::jsonb,12) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l56',5,'am3_l56_gp5','choice','{"stem":"\"At last a raft appeared, ___ the whole family to safety.\"(现在分词修饰 raft,表主动“正…着”)","options":["carried","carrying","to carry","carry"],"answer_index":1,"stem_cn":"终于一只木筏出现,载着全家逃向安全处。","explanation_cn":"现在分词短语修饰前面的名词 raft,表主动“载着…”。✓ a raft appeared, carrying the whole family. ✗ carried(被动)/ carry / to carry:修饰名词表主动用 -ing。"}'::jsonb,13) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l56',5,'am3_l56_gp5','choice','{"stem":"\"We saw a horse ___ bravely across the flooded field.\"(现在分词修饰 horse,表主动“正在…”)","options":["to swim","swim","swimming","swum"],"answer_index":2,"stem_cn":"我们看见一匹马勇敢地凫水横过被淹的田野。","explanation_cn":"现在分词修饰名词 horse,表主动“正在游”。✓ a horse swimming bravely. ✗ swum(过去分词)/ swim / to swim:表主动进行用 -ing。"}'::jsonb,14) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l56',5,'am3_l56_gp5','choice','{"stem":"\"From the attic we watched the water ___ up the meadow.\"(现在分词表正在进行的动作)","options":["to creep","creeping","creep","crept"],"answer_index":1,"stem_cn":"我们从阁楼看着河水漫上草场。","explanation_cn":"感官动词 watch + 名词 + 现在分词,表“看着…正在…”。✓ watched the water creeping up. ✗ crept / creep(此处强调正在进行)/ to creep:进行用 -ing creeping。"}'::jsonb,15) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l56',5,'am3_l56_gp6','choice','{"stem":"\"A line that marks the edge of land is a ___.\"(“边界”用哪个词)","options":["path","corner","center","boundary"],"answer_index":3,"stem_cn":"标示土地边缘的线。","explanation_cn":"标示土地边缘的线是 boundary。✓ the eastern boundary of our farm. ✗ center 中心;✗ corner 角落;✗ path 小路——都不对。"}'::jsonb,16) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l56',5,'am3_l56_gp6','choice','{"stem":"\"A flat structure of logs used to float on water is a ___.\"(“木筏”用哪个词)","options":["roof","raft","wall","bridge"],"answer_index":1,"stem_cn":"用圆木扎成、浮于水面的平台。","explanation_cn":"用圆木扎成、浮于水面的平台是 raft。✓ a raft appeared. ✗ bridge 桥;✗ wall 墙;✗ roof 屋顶——都不对。"}'::jsonb,17) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l56',5,'am3_l56_gp6','choice','{"stem":"\"The base on which a building stands are its ___.\"(“地基”用哪个词)","options":["gardens","chimneys","foundations","windows"],"answer_index":2,"stem_cn":"建筑赖以矗立的底座。","explanation_cn":"建筑赖以矗立的底座是 foundations。✓ a house with sound foundations. ✗ windows 窗;✗ chimneys 烟囱;✗ gardens 花园——都不对。"}'::jsonb,18) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l56',6,NULL,'choice','{"stem":"boundary 的意思是:","options":["边界,界线","角落","中心","小路"],"answer_index":0,"explanation_cn":"boundary = 边界、界线。✓ the eastern boundary 东部边界。"}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l56',6,NULL,'choice','{"stem":"overtake 的意思是:","options":["隐藏","逃离","突然降临,赶上","拒绝"],"answer_index":2,"explanation_cn":"overtake = 突然降临、赶上。✓ misfortune might overtake us 不幸也许会降临。"}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l56',6,NULL,'choice','{"stem":"meadow 的意思是:","options":["草地,草场","沙漠","山峰","港口"],"answer_index":0,"explanation_cn":"meadow = 草地、草场。✓ built in the meadow 盖在草场上。"}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l56',6,NULL,'choice','{"stem":"occurrence 的意思是:","options":["命令","发生的事,事件","承诺","借口"],"answer_index":1,"explanation_cn":"occurrence = 发生的事、事件。✓ a rare occurrence 罕见的事。"}'::jsonb,4) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l56',6,NULL,'choice','{"stem":"juncture 的意思是:","options":["时刻,关头","重量","角度","距离"],"answer_index":0,"explanation_cn":"juncture = 时刻、关头。✓ at the most critical juncture 在最紧急的关头。"}'::jsonb,5) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l56',6,NULL,'choice','{"stem":"submerge 的意思是:","options":["举起","淹没,浸没","晒干","点燃"],"answer_index":1,"explanation_cn":"submerge = 淹没、浸没。✓ almost submerged 几乎被淹。"}'::jsonb,6) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l56',7,NULL,'cloze','{"stem":"第 1 空","context":"The river ___1___ forms the eastern boundary of our farm has always mattered to us. Without it, we ___2___ not make a living. One winter the water rose, and a raft appeared, ___3___ our neighbors to safety. They ___4___ have been frightened, for their house had sound foundations.","blank_no":1,"options":["that","what","whom","whose"],"answer_index":0,"explanation_cn":"关系代词 that 引导定语从句,指物 the river，在从句中作主语。✓ The river that forms the boundary…"}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET payload=EXCLUDED.payload;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l56',7,NULL,'cloze','{"stem":"第 2 空","context":"The river ___1___ forms the eastern boundary of our farm has always mattered to us. Without it, we ___2___ not make a living. One winter the water rose, and a raft appeared, ___3___ our neighbors to safety. They ___4___ have been frightened, for their house had sound foundations.","blank_no":2,"options":["could","can","will","must"],"answer_index":0,"explanation_cn":"Without…引导与现在相反的虚拟,主句用 could。✓ we could not make a living."}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET payload=EXCLUDED.payload;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l56',7,NULL,'cloze','{"stem":"第 3 空","context":"The river ___1___ forms the eastern boundary of our farm has always mattered to us. Without it, we ___2___ not make a living. One winter the water rose, and a raft appeared, ___3___ our neighbors to safety. They ___4___ have been frightened, for their house had sound foundations.","blank_no":3,"options":["carrying","carried","carry","to carry"],"answer_index":0,"explanation_cn":"现在分词短语修饰 raft,表主动“载着…”。✓ a raft appeared, carrying our neighbors."}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET payload=EXCLUDED.payload;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l56',7,NULL,'cloze','{"stem":"第 4 空","context":"The river ___1___ forms the eastern boundary of our farm has always mattered to us. Without it, we ___2___ not make a living. One winter the water rose, and a raft appeared, ___3___ our neighbors to safety. They ___4___ have been frightened, for their house had sound foundations.","blank_no":4,"options":["must","can","would","need"],"answer_index":0,"explanation_cn":"对过去的肯定推测,填 must + have。✓ They must have been frightened."}'::jsonb,4) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET payload=EXCLUDED.payload;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l56',8,NULL,'choice','{"stem":"Why had the neighbors left their farm?","options":["Their low-lying land was flooding and they fled by raft","They sold it for a profit","They moved to the city for work","Their house had burned down"],"answer_index":0,"explanation_cn":"录音说邻居家地势低洼,被上涨的洪水淹了,他们乘木筏逃离。✓ low-lying land flooding, fled by raft."}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l56',8,NULL,'choice','{"stem":"How did the neighboring family finally reach safety?","options":["By swimming across the river","They stayed in the attic until the water fell","By a rescue helicopter","On a raft that the narrator''s family pulled to the bank"],"answer_index":3,"explanation_cn":"录音说邻居乘木筏漂来,叙述者一家用长杆把木筏钩住、拖到自家岸边,他们才脱险。✓ pulled the raft to the bank."}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l56',8,NULL,'choice','{"stem":"Why did the narrator''s family stand to lose little in the flood?","options":["They had flood insurance","Their cattle had already been moved to higher ground","The river never reached their land","Their farm was on a mountain"],"answer_index":1,"explanation_cn":"录音说叙述者家的牲口早已赶到高地,所以几乎不会有损失。✓ cattle moved to higher ground."}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l56',9,NULL,'choice','{"stem":"你想说\"没有这条河,我们就无法谋生\"(与现在相反虚拟):","options":["Without the river, we could not to make a living.","Without the river, we will not make a living.","Without the river, we could not make a living.","Without the river, we can not make a living."],"answer_index":2,"explanation_cn":"Without 引导与现在相反的虚拟,主句用 could not + 动词原形 make;不用 can not、不用 will、make 前不加 to。✓ could not make a living. 场合:说“没有…就不能…”。"}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l56',9,NULL,'choice','{"stem":"你想说\"即便房子几乎被淹,它也会屹立不倒\"(与过去相反虚拟):","options":["The house would stand even if it had been almost submerged.","The house would have stood even if it had been almost submerged.","The house would have stood even if it was almost submerged.","The house will have stood even if it had been almost submerged."],"answer_index":1,"explanation_cn":"与过去相反:主句 would have + 过去分词 stood,if 从句用过去完成式 had been;不用 would stand、不用 was。✓ would have stood … had been submerged. 场合:对过去作与事实相反的假设。"}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l56',9,NULL,'choice','{"stem":"你想说\"他们一定是被上涨的洪水吓着了\"(对过去的推测):","options":["They must to have become frightened by the rising flood.","They must be becoming frightened by the rising flood.","They must became frightened by the rising flood.","They must have become frightened by the rising flood."],"answer_index":3,"explanation_cn":"对过去的肯定推测 must + have + 过去分词 become;不用 must became、不用 must to have、不用 must be becoming。✓ must have become frightened. 场合:根据迹象推断过去“一定…了”。"}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l56',10,NULL,'choice','{"stem":"overtake 的意思是:","options":["突然降临,赶上","逃离","拒绝","隐藏"],"answer_index":0,"explanation_cn":"overtake = 突然降临、赶上。✓ misfortune might overtake us."}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l56',10,NULL,'choice','{"stem":"juncture 的意思是:","options":["距离","重量","时刻,关头","角度"],"answer_index":2,"explanation_cn":"juncture = 时刻、关头。✓ at the most critical juncture."}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l56',10,NULL,'choice','{"stem":"\"Without the river, we ___ not make a living.\"(与现在相反虚拟,主句用情态词过去式)","options":["could","can","will","must"],"answer_index":0,"stem_cn":"没有这条河,我们无法谋生。","explanation_cn":"Without 引导与现在相反的虚拟,主句用情态词过去式 could。✓ we could not make a living. ✗ can / will / must。"}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l56',10,NULL,'choice','{"stem":"\"They ___ have become frightened by the flood.\"(对过去的推测“一定…了”)","options":["need","would","can","must"],"answer_index":3,"stem_cn":"他们一定是被洪水吓着了。","explanation_cn":"对过去的肯定推测“一定…了”用 must + have + 过去分词。✓ They must have become frightened. ✗ can / would / need。"}'::jsonb,4) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l56',10,NULL,'choice','{"stem":"\"make a living\" 的意思是:","options":["搬家","谋生、维持生计","退休","旅行"],"answer_index":1,"explanation_cn":"make a living = 谋生、维持生计。✓ could not make a living."}'::jsonb,5) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l56',10,NULL,'choice','{"stem":"\"out of order\" 的意思是:","options":["井然有序","免费的","卖光了","出故障、坏了"],"answer_index":3,"explanation_cn":"out of order = 出故障、坏了。✓ put the phone out of order."}'::jsonb,6) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l56',10,NULL,'choice','{"stem":"What did the narrator''s family do to welcome each season?","options":["Planted new crops","Held celebrations by the river","Traveled abroad","Repainted the house"],"answer_index":1,"passage":"The river that forms the eastern boundary of our farm has always played an important part in our lives. Without it, we could not make a living, for there is only enough spring water to supply the house, and we must pump from the river for everything else. Over the years the river has become almost a member of the family, and we tell it all our secrets. We know, just as beekeepers know with their bees, that misfortune might overtake us if we kept the great events of our lives from it. In summer we hold special river parties. Sometimes we row upstream to a quiet backwater; sometimes we gather at the old boathouse that a predecessor of ours built in the meadow, close by the deepest pool. We welcome each season by the water — crowning the youngest child with flowers in spring, holding a festival on the longest evening of summer, giving thanks for the harvest in fall, and throwing a green wreath into the current in winter. After a long spell of rain the river may rise above its banks. This is a rare occurrence here, for only our lower fields, a small proportion of the farm, are ever affected. Other farms are less lucky, and flooding can spell disaster for their owners. One hard winter we watched the water creep up the lower meadows. Our cattle had already been moved to higher ground, so we stood to lose little, but we were worried about our nearest neighbors, newcomers whose land lay low. The flood had put the phone out of order, and from an attic window we took turns watching the point where their land met ours. At the most critical juncture, a raft appeared, carrying the whole family, a few hens, the dog, and a cat in a basket. They must have become unduly frightened by the rising water, for their house, which had sound foundations, would have stood stoutly even if it had been almost submerged. The men of our family waded out with long poles, hoping to grapple a corner of the raft and pull it toward our bank. We still think it a small miracle that they managed to do so.","explanation_cn":"课文说他们在河边迎接每个季节:春戴花冠、夏办节庆、秋谢丰收、冬抛花环——都是河边的庆祝。✓ celebrations by the river."}'::jsonb,7) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l56',10,NULL,'choice','{"stem":"Why couldn''t the narrator''s family check on their neighbors at first?","options":["The flood had put the phone out of order","They were all asleep","A bridge had collapsed","The neighbors had moved away"],"answer_index":0,"passage":"The river that forms the eastern boundary of our farm has always played an important part in our lives. Without it, we could not make a living, for there is only enough spring water to supply the house, and we must pump from the river for everything else. Over the years the river has become almost a member of the family, and we tell it all our secrets. We know, just as beekeepers know with their bees, that misfortune might overtake us if we kept the great events of our lives from it. In summer we hold special river parties. Sometimes we row upstream to a quiet backwater; sometimes we gather at the old boathouse that a predecessor of ours built in the meadow, close by the deepest pool. We welcome each season by the water — crowning the youngest child with flowers in spring, holding a festival on the longest evening of summer, giving thanks for the harvest in fall, and throwing a green wreath into the current in winter. After a long spell of rain the river may rise above its banks. This is a rare occurrence here, for only our lower fields, a small proportion of the farm, are ever affected. Other farms are less lucky, and flooding can spell disaster for their owners. One hard winter we watched the water creep up the lower meadows. Our cattle had already been moved to higher ground, so we stood to lose little, but we were worried about our nearest neighbors, newcomers whose land lay low. The flood had put the phone out of order, and from an attic window we took turns watching the point where their land met ours. At the most critical juncture, a raft appeared, carrying the whole family, a few hens, the dog, and a cat in a basket. They must have become unduly frightened by the rising water, for their house, which had sound foundations, would have stood stoutly even if it had been almost submerged. The men of our family waded out with long poles, hoping to grapple a corner of the raft and pull it toward our bank. We still think it a small miracle that they managed to do so.","explanation_cn":"课文说洪水弄断了电话,他们起初无法了解邻居的情况。✓ phone out of order."}'::jsonb,8) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l56',10,NULL,'choice','{"stem":"What appeared on the river carrying the whole neighboring family?","options":["A fishing boat","A wooden bridge","A raft","A truck"],"answer_index":2,"audio":"The river that forms the eastern boundary of our farm has always played an important part in our lives. Without it, we could not make a living, for there is only enough spring water to supply the house, and we must pump from the river for everything else. Over the years the river has become almost a member of the family, and we tell it all our secrets. We know, just as beekeepers know with their bees, that misfortune might overtake us if we kept the great events of our lives from it. In summer we hold special river parties. Sometimes we row upstream to a quiet backwater; sometimes we gather at the old boathouse that a predecessor of ours built in the meadow, close by the deepest pool. We welcome each season by the water — crowning the youngest child with flowers in spring, holding a festival on the longest evening of summer, giving thanks for the harvest in fall, and throwing a green wreath into the current in winter. After a long spell of rain the river may rise above its banks. This is a rare occurrence here, for only our lower fields, a small proportion of the farm, are ever affected. Other farms are less lucky, and flooding can spell disaster for their owners. One hard winter we watched the water creep up the lower meadows. Our cattle had already been moved to higher ground, so we stood to lose little, but we were worried about our nearest neighbors, newcomers whose land lay low. The flood had put the phone out of order, and from an attic window we took turns watching the point where their land met ours. At the most critical juncture, a raft appeared, carrying the whole family, a few hens, the dog, and a cat in a basket. They must have become unduly frightened by the rising water, for their house, which had sound foundations, would have stood stoutly even if it had been almost submerged. The men of our family waded out with long poles, hoping to grapple a corner of the raft and pull it toward our bank. We still think it a small miracle that they managed to do so.","explanation_cn":"课文/录音说在最紧急的关头,一只木筏出现,载着邻居全家。✓ a raft."}'::jsonb,9) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am3_l56',10,NULL,'choice','{"stem":"What did the narrator call their family''s rescue of the neighbors?","options":["A miracle","A mistake","A disaster","A routine"],"answer_index":0,"audio":"The river that forms the eastern boundary of our farm has always played an important part in our lives. Without it, we could not make a living, for there is only enough spring water to supply the house, and we must pump from the river for everything else. Over the years the river has become almost a member of the family, and we tell it all our secrets. We know, just as beekeepers know with their bees, that misfortune might overtake us if we kept the great events of our lives from it. In summer we hold special river parties. Sometimes we row upstream to a quiet backwater; sometimes we gather at the old boathouse that a predecessor of ours built in the meadow, close by the deepest pool. We welcome each season by the water — crowning the youngest child with flowers in spring, holding a festival on the longest evening of summer, giving thanks for the harvest in fall, and throwing a green wreath into the current in winter. After a long spell of rain the river may rise above its banks. This is a rare occurrence here, for only our lower fields, a small proportion of the farm, are ever affected. Other farms are less lucky, and flooding can spell disaster for their owners. One hard winter we watched the water creep up the lower meadows. Our cattle had already been moved to higher ground, so we stood to lose little, but we were worried about our nearest neighbors, newcomers whose land lay low. The flood had put the phone out of order, and from an attic window we took turns watching the point where their land met ours. At the most critical juncture, a raft appeared, carrying the whole family, a few hens, the dog, and a cat in a basket. They must have become unduly frightened by the rising water, for their house, which had sound foundations, would have stood stoutly even if it had been almost submerged. The men of our family waded out with long poles, hoping to grapple a corner of the raft and pull it toward our bank. We still think it a small miracle that they managed to do so.","explanation_cn":"课文结尾说他们至今仍觉得能把木筏拖上岸、救下邻居,是个小小的奇迹。✓ a small miracle."}'::jsonb,10) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
